          expect(screen.getByLabelText('Clear search input')).not.toHaveClass(
            `${prefix}--search-close--hidden`
          );
        } else {
          expect(screen.getByLabelText('Clear search input')).toHaveClass(
            `${prefix}--search-close--hidden`
          );
        }
      }
    );

