      const onKeyDown = jest.fn();
      render(<Search labelText="test-search" onKeyDown={onKeyDown} />);

      await userEvent.type(screen.getByRole('searchbox'), 'test');

      expect(onKeyDown).toHaveBeenCalled();
    });

